  View header=new View(c);menu.setHeaderTitle("Title").setHeaderIcon(new android.graphics.drawable.ColorDrawable(0xff00ff00));check("Title".equals(menu.shirazHeaderTitle())&&menu.shirazHeaderIcon()!=null,"header data");menu.setHeaderView(header);check(menu.shirazHeaderTitle()==null&&menu.shirazHeaderIcon()==null&&menu.shirazHeaderView()==header,"custom header");menu.clearHeader();check(menu.shirazHeaderView()==null,"clear header");
  menu.add(0,1,0,"Select");final int[] calls={0};menu.shirazSetSelectionListener(new MenuItem.OnMenuItemClickListener(){public boolean onMenuItemClick(MenuItem item){calls[0]++;return true;}});check(menu.performIdentifierAction(1,Menu.FLAG_PERFORM_NO_CLOSE)&&!menu.shirazIsClosed()&&calls[0]==1,"selection fallback/no close");check(menu.performIdentifierAction(1,Menu.FLAG_ALWAYS_PERFORM_CLOSE)&&menu.shirazIsClosed(),"close action");
  menu.clear();for(int i=0;i<4096;i++)menu.add("Bounded");try{menu.add("Overflow");throw new AssertionError("item budget bypassed");}catch(IllegalStateException expected){}menu.clear();check(menu.add("Recovered")!=null,"item budget recovery");menu.clear();
