  try{new View(c).showContextMenu();throw new AssertionError("unsupported popup accepted");}catch(UnsupportedOperationException expected){}
  final int[] activityCalls={0};android.app.Activity activity=new android.app.Activity(){public void onCreateContextMenu(ContextMenu m,View view,ContextMenu.ContextMenuInfo info){super.onCreateContextMenu(m,view,info);m.add(0,55,0,"Activity");}public boolean onContextItemSelected(MenuItem item){activityCalls[0]++;return item.getItemId()==55;}};
  View target=new View(c);activity.registerForContextMenu(target);HostContextMenu activityMenu=activity.shirazCreateContextMenu(target);check(activityMenu.performIdentifierAction(55,0)&&activityCalls[0]==1,"activity registration/selection");activity.unregisterForContextMenu(target);check(activity.shirazCreateContextMenu(target).size()==0,"activity unregister");
  MenuItem action=menu.add(0,73,0,"Search");View actionView=new View(c);check(action.setActionView(actionView)==action&&action.getActionView()==actionView&&actionView.getId()==73,"action view identity/default ID");View named=new View(c);named.setId(99);action.setActionView(named);check(named.getId()==99,"preserve action view ID");final int[] expansions={0};action.setOnActionExpandListener(new MenuItem.OnActionExpandListener(){public boolean onMenuItemActionExpand(MenuItem item){expansions[0]++;return true;}public boolean onMenuItemActionCollapse(MenuItem item){return false;}});check(!action.expandActionView()&&expansions[0]==0,"expansion requires flag");action.setShowAsAction(MenuItem.SHOW_AS_ACTION_COLLAPSE_ACTION_VIEW);check(!action.expandActionView()&&expansions[0]==1&&!action.isActionViewExpanded(),"no presenter cannot claim expanded view");check(!action.collapseActionView(),"collapse veto");action.setActionView((View)null);check(action.getActionView()==null&&action.collapseActionView(),"clear action view");
  System.out.println("MENU_MODEL_AND_CALLBACKS_OK");
